package scp_candidate.EIT_Acquisition_Supervisor

import org.sireum._
import art._
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait PublicationComposition_Api {
  def id: Art.BridgeId
  def decision_frame_Id : Art.PortId
  def control_frame_Id : Art.PortId
  def status_frame_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var control_frame: EIT_Acquisition_Supervisor.ControlFrame = $

  def put_control_frame(value : EIT_Acquisition_Supervisor.ControlFrame) : Unit = {
    Contract(
      Modifies(control_frame),
      Ensures(
        control_frame == value
      )
    )
    Spec {
      control_frame = value
    }

    Art.putValue(control_frame_Id, EIT_Acquisition_Supervisor.ControlFrame_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var status_frame: EIT_Acquisition_Supervisor.StatusFrame = $

  def put_status_frame(value : EIT_Acquisition_Supervisor.StatusFrame) : Unit = {
    Contract(
      Modifies(status_frame),
      Ensures(
        status_frame == value
      )
    )
    Spec {
      status_frame = value
    }

    Art.putValue(status_frame_Id, EIT_Acquisition_Supervisor.StatusFrame_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class PublicationComposition_Initialization_Api (
  val id: Art.BridgeId,
  val decision_frame_Id : Art.PortId,
  val control_frame_Id : Art.PortId,
  val status_frame_Id : Art.PortId) extends PublicationComposition_Api

@datatype class PublicationComposition_Operational_Api (
  val id: Art.BridgeId,
  val decision_frame_Id : Art.PortId,
  val control_frame_Id : Art.PortId,
  val status_frame_Id : Art.PortId) extends PublicationComposition_Api {

  // Logika spec var representing port state for incoming data port
  @spec var decision_frame: EIT_Acquisition_Supervisor.DecisionFrame = $

  def get_decision_frame() : Option[EIT_Acquisition_Supervisor.DecisionFrame] = {
    Contract(
      Ensures(
        Res == Some(decision_frame)
      )
    )
    val value : Option[EIT_Acquisition_Supervisor.DecisionFrame] = Art.getValue(decision_frame_Id) match {
      case Some(EIT_Acquisition_Supervisor.DecisionFrame_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port decision_frame.  Expecting 'EIT_Acquisition_Supervisor.DecisionFrame_Payload' but received ${v}")
        None[EIT_Acquisition_Supervisor.DecisionFrame]()
      case _ => None[EIT_Acquisition_Supervisor.DecisionFrame]()
    }
    return value
  }
}
